package com.ibm.websphere.samples.daytrader;

import java.util.List;

/**
 * Generated by the engine (lot V2-2a, RFC-042 section 2): the legacy
 * interceptor chain of every intercepted method, outermost first. Sorted by
 * target class, method name and parameter types.
 */
final class EngineInterceptorBindings {

    private EngineInterceptorBindings() {
    }

    static List<EngineInterceptorChain.Binding> bindings() {
        return List.of(
                EngineInterceptorChain.binding(com.ibm.websphere.samples.daytrader.web.prims.PingCDIBean.class, "getBeanMangerViaCDICurrent", new Class<?>[] {},
                        EngineInterceptorChain.step(com.ibm.websphere.samples.daytrader.web.prims.PingInterceptor.class, "methodInterceptor")),
                EngineInterceptorChain.binding(com.ibm.websphere.samples.daytrader.web.prims.PingCDIBean.class, "getBeanMangerViaJNDI", new Class<?>[] {},
                        EngineInterceptorChain.step(com.ibm.websphere.samples.daytrader.web.prims.PingInterceptor.class, "methodInterceptor")),
                EngineInterceptorChain.binding(com.ibm.websphere.samples.daytrader.web.prims.PingCDIBean.class, "hello", new Class<?>[] {},
                        EngineInterceptorChain.step(com.ibm.websphere.samples.daytrader.web.prims.PingInterceptor.class, "methodInterceptor")));
    }
}
